import{z as A,x as B,o as i,c as d,q as E,j as t,D as r,d as s,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"流算法 Misra–Gries","description":"","frontmatter":{"title":"流算法 Misra–Gries","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/misra-gries.md","filePath":"cs/misra-gries.md","lastUpdated":1791063341000}'),p={name:"cs/misra-gries.md"};function k(m,a,h,C,u,f){const n=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=E('<h1 id="流算法-misra–gries" tabindex="-1">流算法 Misra–Gries <a class="header-anchor" href="#流算法-misra–gries" aria-label="Permalink to &quot;流算法 Misra–Gries&quot;">​</a></h1><div class="epigraph"><p>一遍扫描，$k-1$ 个计数器找出频率 $\\gt n/k$ 的候选项；真频繁项不会漏，假阳性再扫或抽样验证。</p><footer>—— 据 Misra and Gries, Finding Repeated Elements, 1982；Cormode and Hadjieleftheriou 流频繁项综述整理</footer></div><p>上一课<a href="/cs/simulated-annealing">模拟退火</a>收束元启发式。图流课已见识过「一遍流、小内存」的约束；本课换对象：元素流——宇宙（可能的不同项）很大，内存只装得下常数个计数器，要找频繁项。缺口是 Misra–Gries：Boyer–Moore 多数投票的推广。不重写半流图森林；后课外存 I/O。<a href="/cs/graph-streaming">图流</a>的对象是边，本课是元素序列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长 \\(n\\) 的流里，频率超过 \\(n/k\\) 的项至多 \\(k-1\\) 个——这既是空间下界，也说明 \\(k-1\\) 个计数器刚好装得下候选。MG 维护至多 \\(k-1\\) 个 (项, 计数)：新项已在表中就加一；表满且不在，就全体减一、删掉归零者。关键结论：频率 \\(\\gt n/k\\) 的真频繁项到流结束都不会被删光——计数可能被低估，但名字还在表里，因此输出是包含全部真频繁项的候选集。</p><p><span class="marginnote">直觉类比：MG 像一场圆桌抵消。桌上摆 \\(k-1\\) 个杯子代表候选：老熟人来了往他杯里放一枚弹珠；生面孔来了且桌满，就所有杯子各拿走一枚（空杯撤走），生面孔同时被扔掉。每次冲突至少 \\(k\\) 个不同项「各掉一滴血」，谁都别想白打。</span></p><p>Count-Min、SpaceSaving 点名。</p><p>缺口是固定 \\(k\\) 空间，不是排序。</p><h3 id="不是精确直方图" tabindex="-1">不是精确直方图 <a class="header-anchor" href="#不是精确直方图" aria-label="Permalink to &quot;不是精确直方图&quot;">​</a></h3><p>输出是候选不是答案：真频繁项不漏，但假阳性存在——冷门项也可能靠减剩的余数留在表里。估值只有单向下界 \\(\\hat f(e)\\ge f(e)-n/k\\)。要精确频率，拿候选列表再扫一遍原流数准；不要声称一遍就能给出所有项的精确频率。</p><p><span class="marginnote">Misra–Gries 1982。Majority Boyer–Moore 是 \\(k=2\\)。后课外存是另一内存层次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(k\\) 给定后一遍 MG 扫完，产出至多 \\(k-1\\) 个候选及其低估计数；每个候选带单向下界 \\(\\hat f(e)\\ge f(e)-n/k\\)。要滤掉假阳性，第二遍只对候选精确计数——候选至多 \\(k-1\\) 个，这一遍的开销与流长无关地小。</p><p><span class="marginnote">常见误区：把表里的计数当成真实频率。它被「全体减一」反复扣血，只是单向下界；冷门项靠减剩的余数留在表里，就是假阳性的来源。要报频率，第二遍只数这至多 \\(k-1\\) 个候选，开销与流长无关。</span></p>',14)),(i(),t(l,null,{default:r(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%85%83%E7%B4%A0%E6%B5%81%22%5D%20--%3E%20MG%5B%22k-1%20%E4%B8%AA%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20MG%20--%3E%20CAND%5B%22%3E%20n%2Fk%20%E5%80%99%E9%80%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"要更细的频率粒度，可对多个 \\(k\\) 并行跑多套摘要，或按频率分层——本课只点名。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"精髓在「全体减一」：它不是随手清理，而是一次配对抵消——表内 \\(k-1\\) 个不同项各减一，连同进不来的新项，恰是 \\(k\\) 个不同项各被扔掉一次。全流共 \\(n\\) 次出现，抵消至多 \\(n/k\\) 轮，任何项至多被伤 \\(n/k\\) 次；真频繁项出现 \\(\\gt n/k\\) 次，计数便降不到零——「真频繁项不漏」的全部证明就在这里，Boyer–Moore 多数投票是 \\(k=2\\) 的特例。与指纹区分：MG 是确定性的，漏报为零；Count-Min 把项压进哈希桶，用 Markov 不等式换空间，误差是概率的。与 Karger 同属小空间摘要，但对象是元素流，不是图的割。",-1)),a[6]||(a[6]=e("p",null,"每个新元素到达时分三种去向，走一遍就知道谁受伤、谁被丢：",-1)),(i(),t(l,null,{default:r(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E5%85%83%E7%B4%A0%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20HIT%7B%22%E5%B7%B2%E5%9C%A8%E8%AE%A1%E6%95%B0%E8%A1%A8%EF%BC%9F%22%7D%0A%20%20HIT%20--%3E%7C%22%E6%98%AF%22%7C%20INC%5B%22%E8%AF%A5%E8%AE%A1%E6%95%B0%E5%99%A8%E5%8A%A0%E4%B8%80%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E8%A1%A8%E6%9C%AA%E6%BB%A1%22%7C%20ADD%5B%22%E7%99%BB%E8%AE%B0%E6%96%B0%E9%A1%B9%EF%BC%8C%E8%AE%A1%E6%95%B0%E7%BD%AE%E4%B8%80%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E8%A1%A8%E5%B7%B2%E6%BB%A1%22%7C%20DEC%5B%22%E5%85%A8%E8%A1%A8%E5%87%8F%E4%B8%80%EF%BC%8C%E5%88%A0%E5%BD%92%E9%9B%B6%E8%80%85%EF%BC%8C%E6%96%B0%E5%85%83%E7%B4%A0%E4%B8%A2%E5%BC%83%22%5D%0A%20%20INC%20--%3E%20NEXT%5B%22%E5%A4%84%E7%90%86%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%0A%20%20ADD%20--%3E%20NEXT%0A%20%20DEC%20--%3E%20NEXT%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">数字实例：\\(n=100\\)，\\(k=5\\)，元素 \\(a\\) 出现 30 次。每次抵消至多扣它一滴血，抵消总共至多 \\(100/5=20\\) 次，计数至少剩 \\(30-20=10\\)，名字始终在表。反之出现 \\(\\le 20\\) 次的项可能被扣光——候选集因此只多不少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 sketch 的全部空间下界，也不写分布式版（计数器要跨机汇总）。后课默认：频繁项用 MG 或 SpaceSaving。下一课外存与 I/O 模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(k-1\\) 计数器一遍流。</li><li>真 \\(\\gt n/k\\) 不漏；频率低估。</li><li>精确需第二遍。</li><li>出处：Misra and Gries, 1982。</li></ul>',5))])}const D=A(p,[["render",k]]);export{c as __pageData,D as default};
